-- Egypt Top Light — Cairo, the Nile & Aswan
-- 9 days / 8 nights · 7 – 15 November 2026
-- 5* : Sheraton Cairo / Marriott Omar Khayyam (4n) + Acamar Nile Cruise (4n)
-- 3 pricing rows: 3,750 pp double | 1,250 single supplement | 5,600 solo traveller

update q_package_docs set data = $pkg${"title": "Cairo, the Nile & Aswan — 7 to 15 November", "intro": "Nine days with the river in the middle of them. Cairo opens with the Giza Plateau and then the older ground behind it — Memphis, the first capital, and the step pyramid at Sakkara where the whole idea began. Then south to Luxor on the Monday for four nights aboard: Karnak and Luxor Temples the afternoon you board, the Theban west bank at first light, Edfu and Kom Ombo from the deck, and two nights at Aswan with Abu Simbel on the table. You fly back up to Cairo on the Friday with nothing scheduled, and close with the Grand Egyptian Museum and the Coptic quarter before flying home. Private throughout — your own guide, your own vehicle, no group.", "hero": "cairo-giza/sphinx-pyramids.jpeg", "meta": {"ref": "", "pax": 2, "arrival": "2026-11-07", "departure": "2026-11-15"}, "overview": {"days": 9, "nights": 8, "cities": 4}, "hotels": [{"nights": 4, "destination": "Cairo & Giza"}, {"nights": 4, "destination": "Nile Cruise"}], "arrival": {"on": true, "title": "Arrival in Cairo — Saturday 7 November", "description": "Arrival at Cairo International Airport.\nMeet & assist by our representative airside, who stays with you through the visa, passport and customs formalities and collects your luggage with you.\nPrivate air-conditioned transfer to your hotel.\nNothing scheduled for the rest of the day — time to settle, eat and sleep off the journey.\nOvernight in Cairo.", "photo": "arrivedepart/arrival-plane.jpg", "meals": {"breakfast": false, "lunch": false, "dinner": false}, "hotel": "Sheraton Cairo / Marriott Omar Khayyam, 5★ (or equal) — bed & breakfast"}, "days": [{"uid": "nov-d02-giza-memphis-sakkara", "title": "The Giza Plateau, Memphis & Sakkara — Sunday 8 November", "description": "Breakfast at your hotel, then meet your private licensed Egyptologist for the day.\nThe Giza Plateau: the Great Pyramid of Khufu, the pyramids of Khafre and Menkaure, and the panoramic viewpoint where all three line up at once. Entry into a burial chamber is available on the spot, at extra cost.\nThe Great Sphinx and the Valley Temple of Khafre, where the causeway ends in limestone blocks the size of a small car.\nSouth to Memphis, capital of the Old Kingdom: the colossal recumbent Ramses II in his own pavilion and the alabaster sphinx, in a village of palm groves where the city once ran for miles.\nLunch at a local restaurant.\nSakkara, the necropolis of Memphis: the Step Pyramid of Djoser — the first monumental stone building anywhere — the Serapeum, and the mastaba tombs whose painted reliefs of harvest, cattle and market days are still sharp after four and a half thousand years.\nBack to your hotel; evening at leisure. Overnight in Cairo.", "photo": "cairo-giza/pyramids-camel.jpeg", "sites": ["Great Pyramid of Khufu", "Great Sphinx", "Memphis", "Sakkara", "Step Pyramid of Djoser"], "guide": true, "meals": {"breakfast": true, "lunch": true, "dinner": false}, "hotel": "Sheraton Cairo / Marriott Omar Khayyam, 5★ (or equal) — bed & breakfast"}, {"uid": "nov-d03-embark-east-bank", "title": "To Luxor, Check-In & the East Bank — Monday 9 November", "description": "Early breakfast — or a breakfast box if the flight goes before service — and check-out.\nTransfer to Cairo airport for the morning flight to Luxor, around an hour, met on arrival and driven to the mooring.\nCheck-in aboard before lunch. Your cabin is ready and the ship is home for the next four nights.\nLunch on board.\nThe East Bank in the afternoon with your private Egyptologist. Karnak: the avenue of ram-headed sphinxes, the first pylon, and the Great Hypostyle Hall — one hundred and thirty-four columns, the tallest twenty-one metres, still carrying their painted architraves.\nThen Luxor Temple, joined to Karnak by the restored three-kilometre Avenue of Sphinxes, with the standing obelisk of Ramses II at the gate. November light on that stone is the best of the year.\nDinner on board, followed by a belly dancer in the lounge.\nOvernight moored in Luxor.", "photo": "luxor-aswan/hypostyle.jpeg", "sites": ["Check-in aboard", "Karnak Temple", "Luxor Temple", "Avenue of Sphinxes"], "guide": true, "meals": {"breakfast": true, "lunch": true, "dinner": true}, "hotel": "Acamar Nile Cruise, 5★ (or equal) — full board"}, {"uid": "nov-d04-west-bank-edfu", "title": "The Theban West Bank, then Sailing to Edfu — Tuesday 10 November", "description": "An early breakfast and straight across the river, ahead of the heat and the coaches.\nThe Valley of the Kings: royal tombs cut deep into the hillside, their corridors of painted text and star-vaulted ceilings intact. Tutankhamun, Seti I and Nefertari are separately ticketed and can be added on the spot.\nThe Temple of Queen Hatshepsut at El-Deir El-Bahari, three colonnaded terraces built straight into the cliff face at the head of the valley.\nThe Colossi of Memnon, the two seated quartzite giants of Amenhotep III that once fronted a temple larger than Karnak.\nBack aboard, and the ship casts off for Edfu — the afternoon is the river's: sugar cane, water buffalo, ferry boats and the odd kingfisher.\nTea time on the sundeck as you sail.\nDinner on board, then the fancy dress party.\nOvernight moored at Edfu.", "photo": "luxor-aswan/colossi.jpeg", "sites": ["Valley of the Kings", "Temple of Hatshepsut", "Colossi of Memnon", "Sailing to Edfu"], "guide": true, "meals": {"breakfast": true, "lunch": true, "dinner": true}, "hotel": "Acamar Nile Cruise, 5★ (or equal) — full board"}, {"uid": "nov-d05-edfu-komombo-aswan", "title": "Edfu, Kom Ombo & on to Aswan — Wednesday 11 November", "description": "Breakfast on board, then the Temple of Horus at Edfu, reached by horse-drawn carriage from the mooring — the most completely preserved temple in Egypt, with its pylon, courtyard, black granite falcon and roofed sanctuary still holding the barque shrine.\nBack aboard and the ship sails for Kom Ombo.\nA barbecue lunch served on deck while you are under way.\nThe Temple of Kom Ombo, right on the riverbank — the only double temple in Egypt, halved precisely between Sobek the crocodile and Haroeris the elder Horus, with the surgical instruments carved on the outer wall and the crocodile museum alongside.\nThen the last stretch south to Aswan, the banks turning to granite and the water opening out.\nEgyptian Night on board: dinner, and a Nubian show after it.\nOvernight moored in Aswan.", "photo": "luxor-aswan/kom-ombo.jpeg", "sites": ["Temple of Horus, Edfu", "Kom Ombo Temple", "Sobek & Haroeris", "BBQ lunch on deck"], "guide": true, "meals": {"breakfast": true, "lunch": true, "dinner": true}, "hotel": "Acamar Nile Cruise, 5★ (or equal) — full board"}, {"uid": "nov-d06-aswan-abu-simbel", "title": "Aswan — or Abu Simbel — Thursday 12 November", "description": "A full day at Aswan, with the ship moored and all meals aboard.\nThe day runs one of two ways, set by the ship's own programme and confirmed with you on board.\nAswan: the High Dam and the granite quarries, then the Temple of Philae, reached by motor launch to Agilkia Island, where the whole complex was cut into blocks and rebuilt stone by stone to save it from the rising water. Time on the river by felucca, and the Botanical Garden on Kitchener's Island if the schedule allows.\nOr Abu Simbel: south across the desert to the two rock temples of Ramses II and Nefertari — four twenty-metre seated colossi cut into the cliff, and a sanctuary the whole mountain was sliced up and moved to save. By road or by short flight.\nWhichever way the day falls, the other can usually be added as an optional excursion — ask your guide on board and we will arrange it.\nMeals on board; the evening is yours. Overnight moored in Aswan.", "photo": "luxor-aswan/abusimbel.jpeg", "sites": ["Aswan High Dam", "Philae Temple", "Optional: Abu Simbel", "Meals on board"], "guide": true, "meals": {"breakfast": true, "lunch": true, "dinner": true}, "hotel": "Acamar Nile Cruise, 5★ (or equal) — full board"}, {"uid": "nov-d07-checkout-cairo", "title": "Checkout & North to Cairo — Friday 13 November", "description": "Breakfast on board, then checkout with assistance and your luggage taken care of.\nTime in Aswan before you travel if the flight allows — the souk, the corniche, or a last hour on the water.\nTransfer to Aswan airport and the flight up to Cairo, met on arrival.\nCheck-in at your hotel, and the rest of the day is deliberately empty: nothing booked, nothing to be anywhere for.\nYour guide can suggest somewhere to eat, or the hotel will do it. Say the word and we will arrange a Nile dinner cruise for the evening at extra cost.\nOvernight in Cairo.", "photo": "luxor-aswan/nile.jpeg", "sites": ["Checkout", "Flight to Cairo", "Afternoon at leisure"], "guide": false, "meals": {"breakfast": true, "lunch": false, "dinner": false}, "hotel": "Sheraton Cairo / Marriott Omar Khayyam, 5★ (or equal) — bed & breakfast"}, {"uid": "nov-d08-gem-old-cairo", "title": "The Grand Egyptian Museum & Coptic Cairo — Saturday 14 November", "description": "Breakfast at your hotel, then meet your private Egyptologist.\nThe Grand Egyptian Museum at Giza: the hanging obelisk at the entrance, the Ramses II atrium, the grand staircase of royal statuary climbing towards the plateau, and the complete Tutankhamun collection shown together for the first time — over five thousand objects, the death mask among them. Give it the whole morning; it deserves it.\nLunch at a local restaurant.\nCoptic Old Cairo on foot: the Hanging Church suspended on the towers of the Roman fortress, the Church of St Sergius over the crypt where the Holy Family is held to have sheltered, and the Ben Ezra Synagogue where the Geniza documents were found — three faiths inside two hundred metres.\nTime in the Khan El-Khalili bazaar afterwards if you want it, for mint tea at El-Fishawy among the coppersmiths and the spice sellers.\nBack to your hotel. Overnight in Cairo.", "photo": "cairo-giza/inside-gem.jpeg", "sites": ["Grand Egyptian Museum", "Hanging Church", "St Sergius", "Ben Ezra Synagogue", "Khan El-Khalili"], "guide": true, "meals": {"breakfast": true, "lunch": true, "dinner": false}, "hotel": "Sheraton Cairo / Marriott Omar Khayyam, 5★ (or equal) — bed & breakfast"}], "departure": {"on": true, "title": "Departure — Sunday 15 November", "description": "Breakfast at your hotel, subject to your flight timing; a breakfast box is arranged for an early departure.\nCheck-out, with help for your luggage and a late check-out requested where the hotel can give it.\nPrivate air-conditioned transfer to Cairo International Airport in good time.\nFinal meet & assist through check-in and departure formalities — and a safe journey home.", "photo": "arrivedepart/departure-plane.jpg", "meals": {"breakfast": true, "lunch": false, "dinner": false}, "hotel": ""}, "pp": 3750, "sgl": 1250, "showPrice": false, "priceTableOn": true, "priceRows": [{"category": "Per person sharing a double or twin room", "dbl": 3750, "single": 0, "triple": 0, "quad": 0, "hotels": "Cairo — Sheraton Cairo or Marriott Omar Khayyam, or equal (5★)\nNile cruise — Acamar, or equal (5★)"}, {"category": "Single room on a shared booking — supplement per person", "dbl": 0, "single": 1250, "triple": 0, "quad": 0, "hotels": "Cairo — Sheraton Cairo or Marriott Omar Khayyam, or equal (5★)\nNile cruise — Acamar, or equal (5★)"}, {"category": "Solo traveller — one guest travelling alone, private throughout. Figure shown is the full price for the single guest, not a share and not a top-up.", "dbl": 5600, "single": 0, "triple": 0, "quad": 0, "hotels": "Cairo — Sheraton Cairo or Marriott Omar Khayyam, or equal (5★)\nNile cruise — Acamar, or equal (5★)"}], "priceColumns": "all", "roomBasis": "double/twin", "flights": [], "category": "other", "included": "Meet & assist by our representative at Cairo International Airport on arrival and departure, and at Luxor and Aswan on the domestic flights\n8 nights on double/twin room basis — 4 nights Cairo & Giza (bed & breakfast) and 4 nights aboard the Nile cruise (full board)\nFive-star throughout: Sheraton Cairo or the Marriott Omar Khayyam in Cairo, and the Acamar Nile Cruise — or hotels and vessels of the same standard\nFour-night Nile cruise Luxor to Aswan, with every shore excursion and all onboard entertainment as programmed — belly dancer, fancy dress party, barbecue lunch on deck, Egyptian Night and the Nubian show\nDomestic flights within the programme: Cairo – Luxor on Monday 9 November and Aswan – Cairo on Friday 13 November, with airport transfers at both ends\nPrivate air-conditioned vehicle for every transfer and excursion, at your disposal alone — never shared, no group at any point\nPrivate licensed Egyptologist guide on every sightseeing day in Cairo and on all shore excursions\nEntrance fees to every site named in the programme, including the Giza Plateau, Memphis, Sakkara, Karnak, Luxor Temple, three tombs in the Valley of the Kings, Hatshepsut, Edfu, Kom Ombo, Philae, the High Dam and the Grand Egyptian Museum\nMeals as specified on each day — breakfast daily, full board throughout the cruise, and the two Cairo sightseeing lunches\nBottled water in the vehicle throughout\nAll local taxes and service charges\n24/7 support from our Cairo office for the whole nine days\nWritten booking confirmation setting out the payment schedule and cancellation terms in full before any deposit is taken", "excluded": "International airfare to and from Egypt\nEgypt entry visa (USD 36, payable on arrival)\nAbu Simbel, where the ship's Thursday programme puts you in Aswan instead — quoted on request, by road or by short flight\nOptional entry inside the Great Pyramid at Giza, and the separately ticketed tombs of Tutankhamun, Seti I and Nefertari in the Valley of the Kings\nOptional sunrise hot-air balloon over the Luxor west bank, and the optional Nile dinner cruise in Cairo\nLunches and dinners not listed in the programme\nDrinks with meals and anything from the ship's or hotel's bar\nSpa treatments and anything booked directly with the hotel or cruise ship\nTravel insurance\nTipping and gratuities for the guide, driver and ship crew\nPersonal expenses, laundry and telephone calls\nAnything not listed under \"Included\""}$pkg$::jsonb where id = 162;
